  atmoCyan: '#56d6ff',
  ship: '#eaf6ff',
  shipGlow: '#63d6ff',
  shipDark: '#9db8d8',
  engine: '#ffb45c',
  engineCore: '#fff3d6',
  pod: ['#57ffab', '#6fe0ff', '#ffd75e'],
  rock: '#9aa6b8',
  rockDark: '#545e6e',
  rockCrater: '#6a7484',
  sat: '#cdd7e6',
  satPanel: '#3a6ea8',
  satPanelDark: '#264d78',
  beam: '#7df0ff',
  beamCore: '#eafeff',
  hullGood: '#4ade80',
  hullMid: '#facc15',
  hullBad: '#f87171',
  fuel: '#38bdf8',
