          s.hull = Math.max(0, s.hull - e.damage);
          popup(s.x, s.y - 26, '-' + e.damage, '#f87171');
          burst(e.x, e.y, RGB.danger, 18, 220, 0.55, 2.4, true);
          burst(e.x, e.y, RGB.rock, 12, 160, 0.5, 2, false);
          shake(9);
          events |= EVENT_DAMAGE;
