      state.over = true;
      state.cause = ship.fuel <= 0 && ship.hull > 0 ? 'fuel' : 'hull';
      ship.hull = Math.max(0, ship.hull);
      ship.fuel = Math.max(0, ship.fuel);
      return EVENT_OVER;
    }
    return 0;
