      const tailY = s.y - Math.sin(s.angle) * s.radius;
      emit(tailX, tailY, -Math.cos(s.angle) * 90, -Math.sin(s.angle) * 90, 0.3, 2, RGB.engine[0], RGB.engine[1], RGB.engine[2], true);
